window.__NIROGBHUMI_SITE__.push("\" alt=\"\" loading=\"lazy\">\n      <img class=\"world-bg\" src=\"data:image/webp;base64,\" alt=\"Field research notes, photography equipment and anonymised charts\" loading=\"lazy\" decoding=\"async\">\n      <div class=\"world-grade evidence-grade\"></div>\n      <div class=\"evidence-intro reveal\"><p class=\"kicker\">Chapter 03 \u00b7 After we return</p><h2 id=\"evidence-title\">The evidence trail<br><em>stays open.</em></h2><p>This page becomes NirogBhumi's permanent expedition archive. Personal health information is never published without explicit consent.</p></div>\n      <div class=\"archive-console reveal\">\n        <header><div><span class=\"live-dot\"></span><small>Archive status</small><strong>Pre-expedition \u00b7 Framework live</strong></div><div class=\"archive-filters\" role=\"group\" aria-label=\"Filter archive\"><button class=\"active\" type=\"button\" data-filter=\"all\">All</button><button type=\"button\" data-filter=\"research\">Research</button><button type=\"button\" data-filter=\"reports\">Reports</button><button type=\"button\" data-filter=\"stories\">Stories</button><button type=\"button\" data-filter=\"media\">Media</button></div></header>\n        <div class=\"archive-grid\" aria-live=\"polite\">\n          <article data-category=\"research\"><span>Research \u00b7 Planned</span><h3>Study protocol & methodology</h3><p>What is observed, when measurements happen and how limitations are reported.</p><small>Publishes before fieldwork \u2197</small></article>\n          <article data-category=\"research\"><span>Research \u00b7 After</span><h3>Aggregate medical findings</h3><p>Anonymised group-level patterns, context and responsible interpretation.</p><small>No individual medical records \u2197</small></article>\n          <article data-category=\"reports\"><span>Report \u00b7 After</span><h3>Expedition outcomes report</h3><p>Preparation adherence, field observations, operational learning and next steps.</p><small>Downloadable report \u2197</small></article>\n          <article data-category=\"stories\"><span>Stories \u00b7 With consent</span><h3>Participant field diaries</h3><p>First-person reflections on preparation, fear, capability and community.</p><small>Written and audio stories \u2197</small></article>\n          <article data-category=\"media\"><span>Gallery \u00b7 After</span><h3>Photographs & field notes</h3><p>A day-by-day visual record of the people, landscape and work.</p><small>Documentary gallery \u2197</small></article>\n          <article data-category=\"media\"><span>Film \u00b7 After</span><h3>The expedition documentary</h3><p>Short films, interviews and an honest account of what the journey required.</p><small>Video archive \u2197</small></article>\n        </div>\n      </div>\n      <img class=\"section-seam seam-bottom terrain-seam seam-flip-x\" src=\"data:image/webp;base64,\" alt=\"\" loading=\"lazy\">\n    </section>\n\n    <section class=\"registration-world immersive-panel\" id=\"register\" aria-labelledby=\"register-title\">\n      <img class=\"section-seam seam-top canopy-seam seam-flip-x\" src=\"data:image/webp;base64,\" alt=\"\" loading=\"lazy\">\n      <img class=\"world-bg\" src=\"data:image/webp;base64,\" alt=\"A quiet forest expedition camp at blue hour\" loading=\"lazy\" decoding=\"async\"><div class=\"world-grade registration-grade\"></div><div class=\"camp-glow\"></div>\n      <div class=\"botanical-field registration-flora\" aria-hidden=\"true\"><img class=\"flora flora-a\" src=\"data:image/webp;base64,\" alt=\"\"><img class=\"flora flora-b\" src=\"data:image/webp;base64,\" alt=\"\"><img class=\"flora flora-c\" src=\"data:image/webp;base64,\" alt=\"\"></div>\n      <div class=\"registration-intro reveal\"><p class=\"kicker\">Edition 01 \u00b7 Applications nationwide</p><h2 id=\"register-title\">Meet us<br><em>at basecamp.</em></h2><p>This first screen is not a medical clearance or a guarantee of participation. Clinical documents are requested later through an approved secure process.</p><div class=\"registration-meta\"><div><span>Time</span><strong>8\u201310 min</strong></div><div><span>Selection</span><strong>Multi-stage</strong></div><div><span>Group</span><strong>\u224815 people</strong></div></div></div>\n\n      <div class=\"form-shell reveal\">\n        <div class=\"form-progress\" aria-label=\"Application progress\"><span class=\"active\" data-step-indicator=\"1\"><i>1</i>About you</span><span data-step-indicator=\"2\"><i>2</i>Health screen</span><span data-step-indicator=\"3\"><i>3</i>Readiness</span></div>\n        <form id=\"registration-form\" novalidate>\n          <fieldset class=\"form-step active\" data-form-step=\"1\"><legend><span>Step 1 of 3</span>Tell us who you are</legend><div class=\"field-grid\">\n            <label class=\"field field-wide\"><span>Full name *</span><input name=\"fullName\" autocomplete=\"name\" required></label><label class=\"field\"><span>Email *</span><input type=\"email\" name=\"email\" autocomplete=\"email\" required></label><label class=\"field\"><span>Phone / WhatsApp *</span><input type=\"tel\" name=\"phone\" autocomplete=\"tel\" required></label><label class=\"field\"><span>Age *</span><input type=\"number\" name=\"age\" min=\"18\" max=\"80\" inputmode=\"numeric\" required></label><label class=\"field\"><span>City *</span><input name=\"city\" autocomplete=\"address-level2\" required></label><label class=\"field\"><span>State / region *</span><input name=\"state\" autocomplete=\"address-level1\" required></label><label class=\"field\"><span>Country *</span><input name=\"country\" autocomplete=\"country-name\" required></label>\n          </div></fieldset>\n          <fieldset class=\"form-step\" data-form-step=\"2\" hidden><legend><span>Step 2 of 3</span>High-level health screen</legend><p class=\"fieldset-note\">Do not upload prescriptions or medical reports here. Detailed clinical information is collected securely only if you advance.</p><div class=\"field-grid\">\n            <label class=\"field\"><span>Year diagnosed with Type 2 diabetes *</span><input type=\"number\" name=\"diagnosisYear\" min=\"1970\" max=\"2026\" inputmode=\"numeric\" required></label><label class=\"field\"><span>Current treatment *</span><select name=\"treatment\" required><option value=\"\">Select</option><option>Lifestyle guidance only</option><option>Oral medication</option><option>Insulin</option><option>Insulin and oral medication</option><option>Other / unsure</option></select></label><label class=\"field\"><span>Latest HbA1c, if known</span><input type=\"number\" name=\"hba1c\" min=\"3\" max=\"20\" step=\"0.1\" inputmode=\"decimal\" placeholder=\"e.g. 7.2\"></label><label class=\"field\"><span>Current weekly activity *</span><select name=\"activity\" required><option value=\"\">Select</option><option>Mostly sedentary</option><option>1\u20132 active days</option><option>3\u20134 active days</option><option>5+ active days</option></select></label>\n          </div><div class=\"check-group\"><p>Has a doctor diagnosed any of the following?</p><label><input type=\"checkbox\" name=\"conditions\" value=\"kidney\"><span>Kidney disease</span></label><label><input type=\"checkbox\" name=\"conditions\" value=\"vision\"><span>Diabetes-related vision disease</span></label><label><input type=\"checkbox\" name=\"conditions\" value=\"heart\"><span>Heart disease</span></label><label><input type=\"checkbox\" name=\"conditions\" value=\"bp\"><span>Uncontrolled blood pressure</span></label><label><input type=\"checkbox\" name=\"conditions\" value=\"nerve\"><span>Significant nerve or foot complications</span></label><label><input type=\"checkbox\" name=\"conditions\" value=\"none\"><span>None of these</span></label></div></fieldset>\n          <fieldset class=\"form-step\" data-form-step=\"3\" hidden><legend><span>Step 3 of 3</span>Readiness and consent</legend><div class=\"field-grid\">\n            <label class=\"field\"><span>Can you commit about one hour each morning? *</span><select name=\"timeCommitment\" required><option value=\"\">Select</option><option>Yes</option><option>I need to discuss my schedule</option><option>No</option></select></label><label class=\"field\"><span>Available for 5\u20137 days around 14 Nov 2026? *</span><select name=\"availability\" required><option value=\"\">Select</option><option>Yes</option><option>Likely, pending confirmation</option><option>No</option></select></label><label class=\"field field-wide\"><span>Why does this expedition matter to you? *</span><textarea name=\"motivation\" rows=\"5\" minlength=\"80\" maxlength=\"1200\" required placeholder=\"Tell us about your motivation, expectations and what you hope to contribute.\"></textarea><small><span data-count>0</span>/1200</small></label><label class=\"field\"><span>Emergency contact name *</span><input name=\"emergencyName\" autocomplete=\"off\" required></label><label class=\"field\"><span>Emergency contact phone *</span><input type=\"tel\" name=\"emergencyPhone\" autocomplete=\"off\" required></label><label class=\"field field-wide\"><span>Relationship to you *</span><input name=\"emergencyRelationship\" required></label>\n          </div><div class=\"consent-group\"><label><input type=\"checkbox\" name=\"accuracy\" required><span>I confirm the information is accurate to the best of my knowledge. *</span></label><label><input type=\"checkbox\" name=\"selection\" required><span>I understand that applying does not guarantee selection. *</span></label><label><input type=\"checkbox\" name=\"medicine\" required><span>I will not change medication without my treating doctor's guidance. *</span></label><label><input type=\"checkbox\" name=\"privacy\" required><span>I consent to this information being used only to assess and contact me about this expedition, subject to the privacy policy. *</span></label></div></fieldset>\n          <div class=\"form-errors\" role=\"alert\" aria-live=\"assertive\"></div><div class=\"form-actions\"><button class=\"form-back\" type=\"button\" hidden>\u2190 Back</button><button class=\"form-next\" type=\"button\">Continue <span>\u2192</span></button><button class=\"form-submit\" type=\"submit\" hidden>Review application <span>\u2197</span></button></div>\n        </form>\n        <div class=\"form-confirmation\" hidden tabindex=\"-1\"><span>Application review</span><h3>Your form is complete.</h3><p>This prototype validates the application but does not transmit or store health information. Connect it to NirogBhumi's approved secure intake system before launch.</p><button type=\"button\" data-edit-application>Edit application</button></div>\n      </div>\n      <img class=\"section-seam seam-bottom terrain-seam\" src=\"data:image/webp;base64,\" alt=\"\" loading=\"lazy\">\n    </section>\n\n    <section class=\"faq-world\" id=\"faq\" aria-labelledby=\"faq-title\">\n      <img class=\"section-seam seam-top canopy-seam\" src=\"data:image/webp;base64,\" alt=\"\" loading=\"lazy\">\n      <img class=\"faq-foliage\" src=\"data:image/webp;base64,\" alt=\"\" loading=\"lazy\">\n      <div class=\"botanical-field faq-flora\" aria-hidden=\"true\"><img class=\"flora flora-a\" src=\"data:image/webp;base64,\" alt=\"\"><img class=\"flora flora-b\" src=\"data:image/webp;base64,\" alt=\"\"><img class=\"flora flora-c\" src=\"data:image/webp;base64,\" alt=\"\"></div>\n      <div class=\"faq-heading reveal\"><p class=\"kicker\">Before you apply</p><h2 id=\"faq-title\">Clear answers.<br><em>No summit promises.</em></h2></div>\n      <div class=\"faq-list\">\n        <details class=\"reveal\"><summary>Do I need previous trekking experience?<span>+</span></summary><p>No. The planned route is simple to moderate, and the 60-day phase builds readiness. Final participation still depends on medical and fitness clearance.</p></details>\n        <details class=\"reveal\"><summary>Does applying guarantee a place?<span>+</span></summary><p>No. Approximately 15 people will be selected through multiple stages based on medical safety, readiness, commitment and group fit.</p></details>\n        <details class=\"reveal\"><summary>Can I stop my diabetes medicine?<span>+</span></summary><p>No. Never stop or change diabetes medication or insulin without your treating doctor's direction. NirogBhumi does not replace your doctor.</p></details>\n        <details class=\"reveal\"><summary>What happens during the 60 days?<span>+</span></summary><p>Participants follow an approximately one-hour morning routine supported by health review, movement, nutrition and habits, recovery, stress regulation and weekly accountability.</p></details>\n        <details class=\"reveal\"><summary>Will my health information be published?<span>+</span></summary><p>Not as individual medical data. Public findings will be anonymised and aggregated. Personal stories or identifiable media require separate explicit consent.</p></details>\n      </div>\n    </section>\n  </main>\n\n  <footer class=\"site-footer\">\n    <div class=\"footer-mark\"><svg viewBox=\"0 0 42 42\" aria-hidden=\"true\"><path d=\"M21 36c0-15 5-24 14-30-1 15-5 24-14 30Z\"></path><path d=\"M21 36c0-11-4-18-14-23 1 12 5 19 14 23Z\"></path><path d=\"M21 36V15\"></path></svg><strong>NirogBhumi</strong><span>World Diabetes Day Expedition 2026</span></div>\n    <div class=\"footer-contact\"><a href=\"mailto:nirogbhumi@gmail.com\">nirogbhumi@gmail.com</a><a href=\"tel:+917357542882\">+91 73575 42882</a><span>Jaipur \u00b7 Rajasthan \u00b7 India</span></div>\n    <p class=\"footer-disclaimer\">Wellness education and expedition information only. NirogBhumi does not replace medical advice, diagnosis, emergency care or treatment. Speak with your doctor before changing medication, diet or activity.</p>\n    <div class=\"footer-bottom\"><span>\u00a9 2026 NirogBhumi</span><span>Edition 01 \u00b7 World Diabetes Day Expedition</span></div>\n  </footer>\n  <script>\n(() => {\n  const root = document.documentElement;\n  const hero = document.querySelector('.parallax-hero');\n  const depthSections = [...document.querySelectorAll('[data-depth-section]')];\n  const mapStage = document.querySelector('.map-stage');\n  const briefingMap = document.querySelector('.expedition-map');\n  const mapStops = [...document.querySelectorAll('.map-stop')];\n  const trailStory = document.querySelector('.trail-story');\n  const routeMoments = [...document.querySelectorAll('.route-moment')];\n  const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;\n  const finePointer = matchMedia('(hover: hover) and (pointer: fine)').matches;\n  const clamp = (v, min = 0, max = 1) => Math.min(max, Math.max(min, v));\n  const smoothstep = (a, b, v) => { const x = clamp((v - a) / (b - a)); return x * x * (3 - 2 * x); };\n\n  let targetProgress = 0, currentProgress = 0;\n  let targetMouseX = 0, targetMouseY = 0, mouseX = 0, mouseY = 0;\n  let frameId = 0, measureFrameId = 0, lastFrameTime = performance.now();\n\n  const requestRender = () => {\n    if (!frameId && !document.hidden) frameId = requestAnimationFrame(render);\n  };\n\n  const measure = () => {\n    const heroRect = hero?.getBoundingClientRect();\n    const documentDistance = Math.max(1, document.documentElement.scrollHeight - innerHeight);\n    const sectionRects = depthSections.map(section => [section, section.getBoundingClientRect()]);\n    if (hero) {\n      targetProgress = clamp(-heroRect.top / Math.max(1, hero.offsetHeight - innerHeight));\n    }\n    root.style.setProperty('--page-progress', clamp(scrollY / documentDistance).toFixed(5));\n    sectionRects.forEach(([section, rect]) => {\n      const p = clamp((innerHeight - rect.top) / (innerHeight + rect.height));\n      section.style.setProperty('--section-y', (p * 2 - 1).toFixed(4));\n      section.style.setProperty('--section-shift-bg', `${((p * 2 - 1) * -2.5).toFixed(4)}svh`);\n      section.style.setProperty('--section-shift-frame', `${((p * 2 - 1) * 1.6).toFixed(4)}svh`);\n      section.style.setProperty('--section-shift-seam', `${((p * 2 - 1) * .7).toFixed(4)}svh`);\n    });\n    if (mapStage && briefingMap) {\n      const rect = mapStage.getBoundingClientRect();\n      const mapProgress = clamp((innerHeight * .72 - rect.top) / Math.max(1, rect.height - innerHeight * .28));\n      briefingMap.style.setProperty('--map-progress', mapProgress.toFixed(4));\n      const mobileMapStop = Math.min(mapStops.length - 1, Math.max(0, Math.floor(mapProgress * mapStops.length)));\n      mapStops.forEach((stop, index) => {\n        const active = innerWidth <= 680 ? index === mobileMapStop : mapProgress >= .08 + index * .22;\n        stop.classList.toggle('map-active', active);\n      });\n    }\n    if (trailStory) {\n      const rect = trailStory.getBoundingClientRect();\n      const trailProgress = clamp((innerHeight * .7 - rect.top) / Math.max(1, rect.height - innerHeight * .6));\n      const trailTrack = innerWidth <= 680 ? trailProgress : clamp((-rect.top - innerHeight * .92) / Math.max(1, rect.height - innerHeight * 1.92));\n      trailStory.style.setProperty('--trail-progress', trailProgress.toFixed(4));\n      trailStory.style.setProperty('--trail-track', trailTrack.toFixed(4));\n      trailStory.style.setProperty('--trail-x', `${(trailTrack * -400).toFixed(3)}vw`);\n      trailStory.style.setProperty('--trail-fill', `${(trailTrack * 100).toFixed(2)}%`);\n      trailStory.style.setProperty('--trail-dot', `${(8 + trailTrack * 84).toFixed(3)}vw`);\n      if (innerWidth > 680) routeMoments.forEach((moment, index) => moment.classList.toggle('route-active', trailTrack >= Math.max(0, index / 4 - .035)));\n    }\n  };\n\n  const scheduleMeasure = () => {\n    if (measureFrameId || document.hidden) return;\n    measureFrameId = requestAnimationFrame(() => {\n      measureFrameId = 0;\n      measure();\n      requestRender();\n    });\n  };\n\n  function render(time = performance.now()) {\n    frameId = 0;\n    const phone = innerWidth <= 680;\n    const delta = Math.min(40, Math.max(8, time - lastFrameTime || 16.667));\n    lastFrameTime = time;\n    const scrollEase = reducedMotion ? 1 : 1 - Math.pow(1 - (phone ? .27 : .24), delta / 16.667);\n    const pointerEase = reducedMotion ? 1 : 1 - Math.pow(1 - .085, delta / 16.667);\n    currentProgress += (targetProgress - currentProgress) * scrollEase;\n    mouseX += (targetMouseX - mouseX) * pointerEase;\n    mouseY += (targetMouseY - mouseY) * pointerEase;\n    const descent = clamp(currentProgress / .76);\n    const exit = smoothstep(phone ? .88 : .79, 1, currentProgress);\n    root.style.setProperty('--d', descent.toFixed(5));\n    root.style.setProperty('--exit', exit.toFixed(5));\n    root.style.setProperty('--mx', mouseX.toFixed(4));\n    root.style.setProperty('--my', mouseY.toFixed(4));\n    root.style.setProperty('--back-o', (1 - smoothstep(.47, .72, currentProgress)).toFixed(4));\n    root.style.setProperty('--middle-o', (1 - smoothstep(.57, .82, currentProgress)).toFixed(4));\n    root.style.setProperty('--front-o', (1 - smoothstep(.69, .93, currentProgress)).toFixed(4));\n    const vw = value => `${value.toFixed(4)}vw`;\n    const svh = value => `${value.toFixed(4)}svh`;\n    root.style.setProperty('--bg-x', vw(mouseX * -.16)); root.style.setProperty('--bg-y', svh(descent * -2.2 + mouseY * -.12));\n    root.style.setProperty('--sun-x', vw(mouseX * -.25)); root.style.setProperty('--sun-y', svh(descent * -2));\n    root.style.setProperty('--mist-a-x', vw(descent * -5 + mouseX * .3)); root.style.setProperty('--mist-a-y', svh(descent * -2)); root.style.setProperty('--mist-a-o', Math.max(0, .65 - exit * .45).toFixed(4));\n    root.style.setProperty('--mist-b-x', vw(descent * 7 + mouseX * -.2)); root.style.setProperty('--mist-b-y', svh(descent * -3.5)); root.style.setProperty('--mist-b-o', Math.max(0, .46 - exit * .38).toFixed(4));\n    root.style.setProperty('--far-left-x', vw(descent * .7 + mouseX * -.24)); root.style.setProperty('--far-right-x', vw(descent * -.7 + mouseX * -.24)); root.style.setProperty('--far-y', svh(descent * (phone ? -3.2 : -2.4) + mouseY * -.15));\n    root.style.setProperty('--mid-left-x', vw(descent * 1.2 + mouseX * -.42)); root.style.setProperty('--mid-right-x', vw(descent * -1.2 + mouseX * -.42)); root.style.setProperty('--mid-y', svh(-2 + descent * (phone ? -5.3 : -3.8) + mouseY * -.24));\n    root.style.setProperty('--near-left-x', vw(descent * 1.8 + mouseX * -.68)); root.style.setProperty('--near-right-x', vw(descent * -1.8 + mouseX * -.68)); root.style.setProperty('--near-y', svh(-4 + descent * (phone ? -6.4 : -5) + mouseY * -.38));\n    root.style.setProperty('--foreground-x', vw(mouseX * -.95)); root.style.setProperty('--foreground-y', svh(-1 + descent * (phone ? -8 : -4.8) + mouseY * -.55));\n    root.style.setProperty('--cloud-far-x', vw(descent * -5.5 + mouseX * -.18)); root.style.setProperty('--cloud-far-y', svh(descent * -4 + mouseY * -.12));\n    root.style.setProperty('--cloud-mid-x', vw(descent * 6.5 + mouseX * -.34)); root.style.setProperty('--cloud-mid-y', svh(descent * -7 + mouseY * -.2));\n    root.style.setProperty('--cloud-front-x', vw(descent * -9 + mouseX * -.58)); root.style.setProperty('--cloud-front-y', svh(descent * -10 + mouseY * -.32));\n    root.style.setProperty('--title-back-x', vw(mouseX * .12)); root.style.setProperty('--title-back-y', svh(descent * (phone ? 48 : 52) + mouseY * .1));\n    root.style.setProperty('--title-middle-x', vw(mouseX * .18)); root.style.setProperty('--title-middle-y', svh(descent * (phone ? 56 : 61) + mouseY * .14));\n    root.style.setProperty('--title-front-x', vw(mouseX * .24)); root.style.setProperty('--title-front-y', svh(descent * (phone ? 64 : 69) + mouseY * .2));\n    root.style.setProperty('--rays-o', Math.max(0, .3 - exit * .22).toFixed(4)); root.style.setProperty('--rays-x', vw(descent * -1)); root.style.setProperty('--rays-y', svh(descent));\n    root.style.setProperty('--chrome-o', Math.max(0, 1 - exit * .92).toFixed(4)); root.style.setProperty('--scroll-o', Math.max(0, 1 - descent * 1.55).toFixed(4));\n    const unsettled = Math.abs(targetProgress - currentProgress) > .00012 || Math.abs(targetMouseX - mouseX) > .0008 || Math.abs(targetMouseY - mouseY) > .0008;\n    if (unsettled) requestRender();\n  }\n\n  if (finePointer) {\n    addEventListener('pointermove', event => {\n      targetMouseX = clamp((event.clientX / innerWidth - .5) * 2, -1, 1);\n      targetMouseY = clamp((event.clientY / innerHeight - .5) * 2, -1, 1);\n      requestRender();\n    }, { passive: true });\n    document.documentElement.addEventListener('mouseleave', () => { targetMouseX = 0; targetMouseY = 0; requestRender(); });\n  }\n  addEventListener('scroll', scheduleMeasure, { passive: true });\n  addEventListener('resize', scheduleMeasure, { passive: true });\n\n  const expeditionIntro = document.querySelector('.expedition-intro');\n  const finishIntro = () => {\n    document.body.classList.remove('intro-running');\n    expeditionIntro?.setAttribute('data-complete', 'true');\n    setTimeout(() => expeditionIntro?.remove(), 800);\n  };\n  if (reducedMotion) setTimeout(finishIntro, 180);\n  else setTimeout(finishIntro, 3850);\n  addEventListener('pageshow', event => { if (event.persisted) finishIntro(); }, { once: true });\n\n  const revealElements = document.querySelectorAll('.reveal');\n  if (reducedMotion || !('IntersectionObserver' in window)) revealElements.forEach(el => el.classList.add('visible'));\n  else {\n    const revealObserver = new IntersectionObserver((entries, observer) => entries.forEach(entry => {\n      if (!entry.isIntersecting) return;\n      entry.target.classList.add('visible'); observer.unobserve(entry.target);\n    }), { rootMargin: '0px 0px 12% 0px', threshold: .02 });\n    revealElements.forEach(el => revealObserver.observe(el));\n  }\n\n  if (routeMoments.length && 'IntersectionObserver' in window) {\n    const routeObserver = new IntersectionObserver(entries => entries.forEach(entry => {\n      if (entry.isIntersecting) entry.target.classList.add('route-active');\n    }), { rootMargin: '-18% 0px -18% 0px', threshold: .04 });\n    routeMoments.forEach(moment => routeObserver.observe(moment));\n  }\n\n  /* Authentic field-recorded ambience: request immediately, then retry on the first allowed gesture. */\n  const ambientAudio = document.querySelector('#nature-audio');\n  const ambientControl = document.querySelector('.ambient-control');\n  const ambientLabel = ambientControl?.querySelector('[data-ambient-label]');\n  let natureStarting = false, natureOn = true;\n  const setAmbientUI = (playing, label = playing ? 'Sound on' : 'Sound ready') => {\n    ambientControl?.setAttribute('aria-pressed', String(playing));\n    ambientControl?.setAttribute('aria-label', playing ? 'Mute nature ambience' : 'Play nature ambience');\n    if (ambientLabel) ambientLabel.textContent = label;\n  };\n  const activationEvents = ['pointerdown', 'touchstart', 'keydown', 'scroll'];\n  const removeNatureActivation = () => activationEvents.forEach(type => window.removeEventListener(type, startNature));\n  async function startNature() {\n    if (natureStarting || !natureOn) return;\n    if (ambientAudio && !ambientAudio.paused) { setAmbientUI(true); removeNatureActivation(); return; }\n    natureStarting = true;\n    if (ambientAudio) {\n      try {\n        ambientAudio.volume = .55;\n        ambientAudio.muted = false;\n        await ambientAudio.play();\n        setAmbientUI(true);\n        removeNatureActivation();\n      } catch (_) {\n        setAmbientUI(false);\n      } finally {\n        natureStarting = false;\n      }\n      return;\n    }\n    natureStarting = false;\n  }\n  activationEvents.forEach(type => window.addEventListener(type, startNature, { passive: true }));\n  ambientControl?.addEventListener('click', () => {\n    if (natureOn && ambientAudio && !ambientAudio.paused) {\n      natureOn = false; ambientAudio.pause(); setAmbientUI(false, 'Sound off');\n    } else {\n      natureOn = true; startNature();\n    }\n  });\n  startNature();\n\n  const archiveButtons = [...document.querySelectorAll('[data-filter]')];\n  const archiveCards = [...document.querySelectorAll('[data-category]')];\n  archiveButtons.forEach(button => button.addEventListener('click', () => {\n    archiveButtons.forEach(item => item.classList.toggle('active', item === button));\n    archiveCards.forEach(card => card.classList.toggle('filtered-out', button.dataset.filter !== 'all' && card.dataset.category !== button.dataset.filter));\n  }));\n\n  const form = document.querySelector('#registration-form');\n  if (form) {\n    const steps = [...form.querySelectorAll('[data-form-step]')];\n    const indicators = [...document.querySelectorAll('[data-step-indicator]')];\n    const backButton = form.querySelector('.form-back'), nextButton = form.querySelector('.form-next'), submitButton = form.querySelector('.form-submit');\n    const errors = form.querySelector('.form-errors'), confirmation = document.querySelector('.form-confirmation');\n    const motivation = form.querySelector('textarea[name=\"motivation\"]'), counter = form.querySelector('[data-count]');\n    let currentStep = 1;\n    const showStep = (step, moveFocus = true) => {\n      currentStep = clamp(step, 1, steps.length);\n      steps.forEach(panel => { const active = +panel.dataset.formStep === currentStep; panel.hidden = !active; panel.classList.toggle('active', active); });\n      indicators.forEach(indicator => indicator.classList.toggle('active', +indicator.dataset.stepIndicator <= currentStep));\n      backButton.hidden = currentStep === 1; nextButton.hidden = currentStep === steps.length; submitButton.hidden = currentStep !== steps.length; errors.textContent = '';\n      if (moveFocus) form.querySelector(`[data-form-step=\"${currentStep}\"] legend`)?.scrollIntoView({ behavior: reducedMotion ? 'auto' : 'smooth', block: 'center' });\n    };\n    const validateCurrentStep = () => {\n      const fields = [...form.querySelector(`[data-form-step=\"${currentStep}\"]`).querySelectorAll('[required]')]; let firstInvalid, invalidCount = 0;\n      fields.forEach(field => { const valid = field.checkValidity(); field.closest('.field')?.classList.toggle('invalid', !valid); if (!valid) { invalidCount += 1; firstInvalid ||= field; } });\n      if (!invalidCount) { errors.textContent = ''; return true; }\n      errors.textContent = `Please complete ${invalidCount} required ${invalidCount === 1 ? 'field' : 'fields'} before continuing.`;\n      firstInvalid?.focus({ preventScroll: true }); firstInvalid?.scrollIntoView({ behavior: reducedMotion ? 'auto' : 'smooth', block: 'center' }); return false;\n    };\n    nextButton.addEventListener('click', () => { if (validateCurrentStep()) showStep(currentStep + 1); });\n    backButton.addEventListener('click', () => showStep(currentStep - 1));\n    form.addEventListener('input', event => { event.target.closest('.field')?.classList.remove('invalid'); if (event.target === motivation && counter) counter.textContent = motivation.value.length; });\n    const none = form.querySelector('input[name=\"conditions\"][value=\"none\"]'), conditions = [...form.querySelectorAll('input[name=\"conditions\"]')];\n    conditions.forEach(input => input.addEventListener('change', () => { if (input === none && input.checked) conditions.filter(item => item !== none).forEach(item => item.checked = false); else if (input.checked && none) none.checked = false; }));\n    form.addEventListener('submit', event => { event.preventDefault(); if (!validateCurrentStep()) return; form.hidden = true; confirmation.hidden = false; confirmation.focus(); });\n    confirmation?.querySelector('[data-edit-application]')?.addEventListener('click', () => { confirmation.hidden = true; form.hidden = false; showStep(3); });\n    showStep(1, false);\n  }\n\n  document.querySelectorAll('.faq-list details').forEach(detail => detail.addEventListener('toggle', () => {\n    if (detail.open) document.querySelectorAll('.faq-list details[open]').forEach(other => { if (other !== detail) other.open = false; });\n  }));\n\n  document.addEventListener('visibilitychange', () => {\n    if (document.hidden) {\n      cancelAnimationFrame(frameId);\n      cancelAnimationFrame(measureFrameId);\n      frameId = 0;\n      measureFrameId = 0;\n      ambientAudio?.pause();\n    } else {\n      lastFrameTime = performance.now();\n      scheduleMeasure();\n      if (natureOn) startNature();\n    }\n  });\n  measure(); requestRender();\n})();\n\n</script>\n</body>\n</html>\n");